test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Add a new @context with Response Status Code set to 400     and
        Add a new @context with Response reason set to 'Bad Request'     and
        Add a new @context with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/InvalidRequest' and Response Body Title is a string and is not ${EMPTY} and Response Body Detail is a string and is not ${EMPTY} and Response Boty Title is not equal to Response Body Detail
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts'
        method set to 'POST'
        Add a new @context based on the payload defined in the file @context-incorrect.json
}

